// "Lively" — the kit's one motion language. Three springs and one exit, so a
// press, a toggle and a sheet all move like parts of the same instrument.
//
// The springs are Motion transitions, plain objects with no import, so a host
// can hand them straight to `motion/react` and the kit can read them without
// Motion installed. The CSS parts of the kit play the same springs through
// `--move-spring-*` in theme.css; `LIVELY_CSS` below holds those strings,
// generated by Motion's own `spring(visualDuration, bounce)` and kept in step
// by a test.

/** A duration-based Motion spring. */
export interface LivelySpring {
  readonly type: 'spring';
  /** Seconds the spring takes to visually arrive. */
  readonly visualDuration: number;
  readonly bounce: number;
}

/** A Motion tween with a cubic Bézier. */
export interface LivelyTween {
  readonly type: 'tween';
  /** Seconds. */
  readonly duration: number;
  readonly ease: readonly [number, number, number, number];
}

/** A press going in and coming back out. */
export const LIVELY_PRESS: LivelySpring = { type: 'spring', visualDuration: 0.15, bounce: 0.15 };
/** Toggles, the selection highlight, menus, popovers, list rows, a value following its source. */
export const LIVELY_UI: LivelySpring = { type: 'spring', visualDuration: 0.28, bounce: 0.15 };
/** Panels, sheets, view switches. */
export const LIVELY_SURFACE: LivelySpring = { type: 'spring', visualDuration: 0.36, bounce: 0.08 };
/** Anything leaving: quick and accelerating, out of the way. */
export const LIVELY_EXIT: LivelyTween = { type: 'tween', duration: 0.12, ease: [0.4, 0, 1, 1] };

/** How far a pressed control sinks. */
export const LIVELY_PRESS_SCALE = 0.97;
/** Seconds between one child and the next in a staggered entrance. */
export const LIVELY_STAGGER = 0.035;
/** The most a whole stagger may take, first child to last, in seconds. */
export const LIVELY_STAGGER_MAX = 0.2;

/**
 * The delay, in seconds, for child `index` of `count`. The step shrinks for a
 * long run so the last child still starts within `LIVELY_STAGGER_MAX`.
 */
export function livelyStagger(index: number, count: number): number {
  if (count <= 1 || index <= 0) return 0;
  const step = Math.min(LIVELY_STAGGER, LIVELY_STAGGER_MAX / (count - 1));
  return Math.min(index, count - 1) * step;
}

/** A spring as CSS: its settle time and its `linear()` easing. */
export interface LivelyCss {
  /** CSS time, e.g. `300ms`. */
  readonly duration: string;
  /** A CSS `linear()` easing. */
  readonly easing: string;
}

/**
 * The springs as CSS — Motion's `spring(visualDuration, bounce).toString()`,
 * split into duration and easing. theme.css carries the same strings as
 * `--move-spring-press`, `--move-spring-ui` and `--move-spring-surface`.
 */
export const LIVELY_CSS: {
  readonly press: LivelyCss;
  readonly ui: LivelyCss;
  readonly surface: LivelyCss;
  readonly exit: LivelyCss;
} = {
  press: {
    duration: '300ms',
    easing: 'linear(0, 0.3505, 0.7432, 0.9336, 0.9951, 1.0062, 1.0045, 1.0019, 1.0005, 1)',
  },
  ui: {
    duration: '550ms',
    easing: 'linear(0, 0.1298, 0.3693, 0.5949, 0.7654, 0.8784, 0.9458, 0.9819, 0.9988, 1.0052, 1.0063, 1.0053, 1.0037, 1.0024, 1.0014, 1.0007, 1, 1)',
  },
  surface: {
    duration: '550ms',
    easing: 'linear(0, 0.0832, 0.2515, 0.4312, 0.5896, 0.7159, 0.8104, 0.8777, 0.9238, 0.9543, 0.9738, 0.9858, 0.9929, 0.9969, 0.9991, 1.0001, 1, 1)',
  },
  exit: { duration: '120ms', easing: 'cubic-bezier(0.4, 0, 1, 1)' },
};
